function rgPaint(g,q){const T=+g.dataset.t,w=+(g.querySelector(".rga").getAttribute("stroke-width")),full=g.querySelector(".rgf"),arc=g.querySelector(".rga"),head=g.querySelector(".rgh"),sd=g.querySelector(".rgsd"),base=g.dataset.c;q=Math.max(0,Math.min(q,5));arc.setAttribute("stroke",base);arc.setAttribute("stroke-dashoffset",(-w/2).toFixed(2));const seg=f=>Math.max(.01,T*f-w);if(q<=1){full.setAttribute("opacity","0");arc.setAttribute("opacity",q>0.002?"1":"0");arc.setAttribute("stroke-dasharray",`${seg(q).toFixed(2)} ${T}`);head.setAttribute("opacity","0");sd.setAttribute("opacity","0")}else{const fr=q-Math.floor(q)||1;full.setAttribute("opacity","1");arc.setAttribute("opacity","1");head.setAttribute("fill",base);arc.setAttribute("stroke-dasharray",`${seg(fr).toFixed(2)} ${T}`);try{const e=Math.max(w/2,T*fr-w/2),p=arc.getPointAtLength(e),s=arc.getPointAtLength((e+5)%T);head.setAttribute("cx",p.x);head.setAttribute("cy",p.y);head.setAttribute("opacity","1");sd.setAttribute("cx",s.x);sd.setAttribute("cy",s.y);sd.setAttribute("opacity",".55")}catch(e){}}}
