function animRings(){const svg=document.querySelector(".rgs");if(!svg)return;const G=[...svg.querySelectorAll(".rg1")],N=[...document.querySelectorAll(".rl2 b[data-n]")],to=G.map(g=>+g.dataset.q),nt=N.map(b=>+b.dataset.n),from=RGPREV||{q:to.map(()=>0),n:nt.map(()=>0)};RGPREV={q:to,n:nt};const same=to.every((v,i)=>v===from.q[i]);if(same){G.forEach((g,i)=>rgPaint(g,to[i]));return}if(window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches){G.forEach((g,i)=>rgPaint(g,to[i]));N.forEach((b,i)=>rgNum(b,nt[i]));return}const ease=t=>-(Math.cos(Math.PI*t)-1)/2,T0=performance.now(),plan=G.map((g,i)=>{const a=from.q[i]||0,d=Math.abs(to[i]-a);return{a,delay:i*160,dur:Math.min(4800,1900+1100*Math.min(d,3))}});G.forEach((g,i)=>rgPaint(g,plan[i].a));const step=now=>{if(!svg.isConnected)return;let fim=true;G.forEach((g,i)=>{const P=plan[i],t=Math.max(0,Math.min(1,(now-T0-P.delay)/P.dur));if(t<1)fim=false;const k=ease(t);rgPaint(g,P.a+(to[i]-P.a)*k);const b=N[i];if(b){const na=from.n[i]||0;rgNum(b,na+(nt[i]-na)*k)}});if(!fim)requestAnimationFrame(step)};requestAnimationFrame(step)}
