function openSheet(k){SH={k,q:"",sel:null,mul:1};renderSheet()}
function closeSheet(){SH=null;const s=$("#sheet");s.hidden=true;s.innerHTML=""}
function flist(){const q=nrm(SH.q.trim()),rec=[...new Set(Object.keys(S.food).sort().reverse().flatMap(k=>S.food[k].map(e=>e[0])))].slice(0,6),row=f=>`<div class="fr" data-fsel="${f[0]}"><div>${f[1]}<small>${Math.round(f[2]*f[4]/100)} kcal · ${f1(f[3]*f[4]/100)} g prot. por porção (${f[4]} g)</small></div><span class="addc">${I("plus",18)}</span></div>`;
if(q){const r=FOOD.filter(f=>nrm(f[1]).includes(q));return r.length?r.map(row).join(""):`<p class="m">Nada encontrado. Tente outro nome.</p>`}
return(rec.length?`<h3 class="sec" style="margin-top:12px">Recentes</h3>${rec.map(id=>FOOD.find(f=>f[0]==id)).filter(Boolean).map(row).join("")}`:"")+`<h3 class="sec" style="margin-top:12px">Todos</h3>${FOOD.filter(f=>!rec.includes(f[0])).map(row).join("")}`}
function renderSheet(){const s=$("#sheet");if(!SH){s.hidden=true;return}s.hidden=false;let h="";const L=S.log[dt]||{};
if(SH.k=="peso")h=`<h2>Registrar medidas</h2><p class="m">${dt==td()?"Hoje":fd(dt)}. Pese-se de manhã, em jejum, depois do banheiro.</p><div class="r"><div><label>Peso (kg)</label><input id="spe" inputmode="decimal" value="${L.peso??""}"></div><div><label>Cintura no umbigo (cm)</label><input id="sci" inputmode="decimal" value="${L.cint??""}"></div></div><button class="p wide lg" id="ssv" style="margin-top:16px">Salvar</button>`;
else if(SH.k=="estado")h=`<h2>Como você está?</h2><label>Apetite</label>${seg("fome",L,[1,2,3,4,5],["😶","🙁","😐","🙂","😋"])}<label>Azia / refluxo</label>${seg("azia",L,[0,1,2,3],["Nada","Leve","Média","Forte"])}<div class="r"><div><label>Sono (h)</label><input data-k="sono" inputmode="decimal" value="${L.sono??""}"></div><div><label>Passos</label><input data-k="passos" inputmode="numeric" value="${L.passos??""}"></div></div>${S.med?`<label style="margin-top:12px">${esc(S.med.nome||"Medicação")} aplicada hoje (${esc(S.med.un||"mg")})</label><input data-k="dose" inputmode="decimal" placeholder="Preencha só no dia da aplicação" value="${L.dose??""}">`:""}<label style="margin-top:12px">Observações</label><textarea data-k="nota" rows="2">${esc(L.nota||"")}</textarea><button class="p wide lg" data-close="1" style="margin-top:16px">Pronto</button>`;
else if(SH.k=="ex"){h=exSheet(SH.i)}
else if(SH.k=="cf"){h=`<h2 style="margin:6px 40px 16px 0">${SH.msg}</h2><button class="p wide lg" id="cfy" style="background:var(--wa)">${SH.yes}</button><button class="wide ghost" data-close="1">Cancelar</button>`}
else if(SH.k=="skip"){const md=SH.mode;h=`<h2>${SH.fp?"Nenhuma série marcada":"Hoje sem musculação"}</h2><p class="m">${SH.fp?"Você está finalizando sem ter marcado nenhuma série. O que você fez hoje?":"O que você fez hoje no lugar do treino?"}</p><div class="tg">${[["Caminhada","🚶 Caminhada"],["Corrida","🏃 Corrida"],["Outro","🚴 Outro cardio"]].map(x=>`<button class="${md==x[0]?"on":""}" data-skm="${x[0]}">${x[1]}</button>`).join("")}</div>${md?`<div class="r"><div><label>Tempo (min)</label><input id="kmi" inputmode="numeric"></div><div><label>Distância (km)</label><input id="kkm" inputmode="decimal" placeholder="opcional"></div></div><div class="r" style="margin-top:10px"><div><label>FC média (bpm)</label><input id="kfc" inputmode="numeric" placeholder="opcional"></div><div><label>Calorias (relógio)</label><input id="kca" inputmode="numeric" placeholder="opcional"></div></div><p class="m" id="kpace" style="margin:8px 0 0"></p><button class="p wide lg" id="sksv" style="margin-top:12px">Salvar ${md=="Outro"?"cardio":md.toLowerCase()}</button>`:""}<button class="wide" id="skrest" style="margin-top:12px">😴 Não fiz nada hoje (descanso)</button>${SH.fp?`<button class="wide ghost" data-close="1">Voltar ao treino</button><button class="wide ghost" data-tcan="1" style="color:var(--wa)">Descartar sem registrar nada</button>`:""}`}
else{const m=+SH.k.split(":")[1];if(SH.sel){const f=FOOD.find(x=>x[0]==SH.sel),g=Math.round(f[4]*SH.mul);h=`<button class="lk" data-fsel="">${I("back",16)} Voltar à busca</button><h2>${f[1]}</h2><p class="m">${f[2]} kcal e ${f1(f[3])} g de proteína por 100 g</p><div class="tg">${[[.5,"½ porção"],[1,"1 porção"],[1.5,"1½"],[2,"2 porções"]].map(x=>`<button class="${SH.mul==x[0]?"on":""}" data-mul="${x[0]}">${x[1]}</button>`).join("")}</div><label>Quantidade (g ou ml)</label><input id="sgr" inputmode="decimal" value="${g}"><div class="kp"><div><b id="skc">${Math.round(f[2]*g/100)}</b><small>kcal</small></div><div><b id="spr">${f1(f[3]*g/100)}</b><small>g proteína</small></div><div><b style="font-size:15px;line-height:1.9">${NM[m]}</b><small>refeição</small></div></div><button class="p wide lg" id="sfa">Adicionar</button>`}
else h=`<h2>Adicionar ao ${NM[m]}</h2><input id="fsearch" placeholder="🔎 Buscar alimento" value="${esc(SH.q)}" autocomplete="off"><button class="wide ghost" data-mccb="1" style="margin:8px 0 0">${I("cam",16)} Ler código de barras da embalagem</button>${favLista(m)}<div id="flist">${flist()}</div>`}
s.innerHTML=`<div class="sbg" data-close="1"></div><div class="sb" role="dialog" aria-modal="true"><div class="grab"></div><button class="ib sx" data-close="1" aria-label="Fechar">${I("x",18)}</button>${h}</div>`}

