function impSaude(t){t=String(t||"");const raw=k=>{const m=t.match(new RegExp(k+"\\s*[=:]\\s*\\[?\\s*([\\d.,]+)","i"));return m?m[1]:null},ps=raw("passos"),pe=raw("peso"),so=raw("sono"),ka=raw("ativa");if(ps==null&&pe==null&&so==null&&ka==null)return"Não encontrei dados do atalho no texto. Ele deve começar com MC;passos=…";const L=S.log[td()]=S.log[td()]||{},r=[];
if(ps!=null){const v=parseInt(ps.replace(/[.,]/g,""),10);if(v>=0&&v<100000){L.passos=v;r.push(v.toLocaleString("pt-BR")+" passos")}}
if(pe!=null){const v=parseFloat(pe.replace(",","."));if(v>=40&&v<=250){L.peso=Math.round(v*100)/100;r.push(f1(v,1)+" kg")}}
if(so!=null){let v=parseFloat(so.replace(/\.(?=\d{3}\b)/g,"").replace(",","."));if(v>=1440)v=v/3600;else if(v>=24)v=v/60;if(v>0&&v<16){L.sono=Math.round(v*60)/60;r.push(fhm(L.sono)+" de sono")}}
if(ka!=null){const v=parseFloat(ka.replace(/\.(?=\d{3}\b)/g,"").replace(",","."));if(v>=0&&v<5000){L.kat=Math.round(v);r.push(L.kat+" kcal ativas")}}
if(!r.length)return"Os valores do texto não parecem válidos.";S.hk={d:td(),h:new Date().toTimeString().slice(0,5),r:r.join(" · ")};sv();return"✅ Importado: "+r.join(" · ")}
